#!/usr/bin/env python3
import json,html,pathlib,collections,itertools
R=pathlib.Path(__file__).resolve().parent; ROOT=R.parent
b=json.load(open(ROOT/"data/session-d2d25025/board.json")); flags=json.load(open(ROOT/"data/session-d2d25025/flagged.json"))
rows=b["rows"]; clean=[h for h in b["high_picks"] if not h["audit_issues"]]
CSS="body{font-family:system-ui;margin:24px;max-width:1200px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border:1px solid #ccc;padding:5px;text-align:left}a{color:#06c}.H{color:#080;font-weight:700}"
def page(t,body,back=True): return f"<!doctype html><meta charset=utf-8><title>{html.escape(t)}</title><style>{CSS}</style><h1>{html.escape(t)}</h1>{'<p><a href=index.html>Dashboard</a></p>' if back else ''}{body}"
def tbl(rs):
    h="<table><tr><th>Date (UTC)</th><th>Sport</th><th>Match</th><th>Venue</th><th>Our pick (match winner)</th><th>Model prob</th><th>Fair odds</th><th>Confidence</th><th>Markets investigated</th><th>Official source</th><th>Audit</th></tr>"
    for r in rs: h+=f"<tr><td>{r['start_utc']}</td><td>{r['sport']}</td><td>{html.escape(r['away'])} at {html.escape(r['home'])}</td><td>{html.escape(r['venue']) or '— blank (unverified)'}</td><td>{html.escape(r['pick'] or '')}</td><td>{r.get('pick_prob','')}</td><td>{r.get('pick_fair_american','')}</td><td>{r['confidence']}</td><td>{', '.join(r['markets'])}</td><td><a href='{r['source_url']}'>{html.escape(r['source_label'])}</a></td><td>{'; '.join(r['audit_issues']) or 'ok'}</td></tr>"
    return h+"</table>"
(R/"index.html").write_text(page("OLBG4 — Board AD dashboard (22 Oct 2026)",f"""<p>Audited desk: <b>{b['summary']['fixtures']} fixtures</b> ({', '.join(f'{k} {v}' for k,v in b['summary']['sports'].items())}), every row with an official source link. Own originated lines only — no bookmaker/OLBG price read. Excluded: soccer, boxing, UFC/MMA, football/American football, hurling, horse racing, cycling, specials.</p><p>Confidence (recomputed): {b['summary']['confidence']} · High selections audited: {b['summary']['high_selections_audited']}, clean &amp; inside −250…+10,000: <b>{b['summary']['high_in_window_clean']}</b> · Flags: {b['summary']['flags']} (see Flagged page — do not block publication).</p><nav><a href=entries.html>All entries</a> · <a href=picks.html>High-confidence picks &amp; predictions</a> · <a href=markets.html>Markets</a> · <a href=coverage.html>Coverage</a> · <a href=methodology.html>Methodology</a> · <a href=sources.html>Sources &amp; live checks</a> · <a href=flagged.html>Flagged for Review</a> · <a href=verification.html>Verification</a></nav><h2>Per-sport</h2><ul>{''.join(f"<li><a href='sports/{s}.html'>{s}</a> ({n})</li>" for s,n in collections.Counter(r['slug'] for r in rows).items())}</ul><h2>Next fixtures</h2>{tbl(rows[:15])}<p>Data: <a href=../data/session-d2d25025/board.json>board.json</a></p>""",back=False))
(R/"entries.html").write_text(page("All entries — Board AD",tbl(rows)))
(R/"picks.html").write_text(page("High-confidence picks (−250…+10,000, prob ≥70%) — Board AD","".join(f"<article><h3>{html.escape(h['selection'])} — {html.escape(h['match'])}</h3><p>Market: {h['market']} · prob {h['prob']} · fair {h['fair_american']} · {h['word_count']} words</p><p>{html.escape((h.get('prediction') or {}).get('text',''))}</p><p>Facts &amp; source: <a href='{h.get('source_url') or 'https://api-web.nhle.com/v1/standings/now'}'>official source</a></p></article>" for h in clean) or "<p>None.</p>"))
mk=collections.Counter()
for r in rows:
 for m in r["markets"]: mk[m]+=1
(R/"markets.html").write_text(page("Markets investigated — Board AD","<table><tr><th>Market</th><th>Rows priced</th></tr>"+"".join(f"<tr><td>{k}</td><td>{v}</td></tr>" for k,v in mk.most_common())+"</table><p>Investigated per match: match winner (moneyline), handicap (puck line ±1.5 NHL / run line MLB / series handicap LoL), match total, team totals where the audited desk priced them. Markets not priced by the originating model are not invented here.</p>"))
(R/"coverage.html").write_text(page("Coverage — Board AD",f"<p>Priced &amp; audited: {b['summary']['sports']}. Not published (no independently verified official numeric input in this session — left blank, flagged, never inferred): NBA basketball, ATP/WTA tennis, cricket, rugby union/league, PDC darts, snooker, golf, volleyball, handball, badminton, table tennis, aussie rules, greyhounds, other esports. OLBG.com used only as taxonomy/exclusion cross-check, never as a price or fixture source.</p>"))
(R/"methodology.html").write_text(page("Methodology — Board AD","<p>Board AD independently re-audits Board AB's originated desk (<code>data/session-1695b749/desk.json</code>): it checks every row's source domain is an official league API (api-web.nhle.com / statsapi.mlb.com / esports-api.lolesports.com), recomputes fair American odds from model probability, recomputes confidence (High requires prob ≥0.70 AND fair odds −250…+10,000; Medium ≥0.55), checks High predictions are ≥30 words, unique, and inside the odds window. Failures go to Flagged, values are never filled in. Live spot re-verification (NHL schedule/standings, MLB World Series) was re-read from official APIs on 2026-10-22 — see Sources.</p>"))
(R/"sources.html").write_text(page("Sources &amp; live checks — Board AD","<table><tr><th>Check</th><th>Official source</th><th>Result</th><th>Status</th></tr>"+"".join(f"<tr><td>{html.escape(c['check'])}</td><td><a href='{c['url']}'>{html.escape(c['url'])}</a></td><td>{html.escape(c['result'])}</td><td>{c['status']}</td></tr>" for c in b["live_checks"])+"</table>"))
(R/"flagged.html").write_text(page("Flagged for Review — Board AD","<p>These items do not block publication. Review after the site is live.</p><table><tr><th>Fixture</th><th>Issue</th><th>Detail</th><th>Source</th></tr>"+"".join(f"<tr><td>{f['fixture']}</td><td>{html.escape(f['kind'])}</td><td>{html.escape(f['detail'])}</td><td><a href='{f['source_url']}'>source</a></td></tr>" for f in flags)+"</table>"))
(R/"verification.html").write_text(page("Verification — Board AD",f"<p>Build: <code>python3 session-d2d25025/build.py &amp;&amp; python3 session-d2d25025/render.py &amp;&amp; python3 session-d2d25025/verify.py</code></p><p>{b['summary']}</p><p>Key irregularity: of 68 selections labelled High by Board AB, only {b['summary']['high_in_window_clean']} are simultaneously prob ≥0.70, fair odds inside −250…+10,000, and carry a unique ≥30-word prediction. The rest are flagged individually on the Flagged page rather than relabelled silently. Under a strict moneyline-only recomputation, only 2 of 96 fixtures reach High — the −250 floor and 70% floor overlap only at prob 0.700–0.714.</p>"))
for slug,rs in itertools.groupby(sorted(rows,key=lambda x:x["slug"]),key=lambda x:x["slug"]):
    rs=list(rs); (R/f"sports/{slug}.html").write_text(page(f"{rs[0]['sport']} — Board AD","<p><a href=../index.html>Dashboard</a></p>"+tbl(rs),back=False))
print("rendered",len(rows),"rows,",len(clean),"clean high picks")
